	/**
	 * 保持するコンテナのListを返します。
	 *
	 * @return コンテナのList
	 */
	public List<MCContainer> getContainers(){
		List<MCContainer> ret = super.getContainers();
		if(!MCCollectionUtil.contains(ret, getCndR())) ret.add(getCndR());
		if(!MCCollectionUtil.contains(ret, getBulkSetR())) ret.add(getBulkSetR());
		if(!MCCollectionUtil.contains(ret, getRslt1L())) ret.add(getRslt1L());
		if(!MCCollectionUtil.contains(ret, getRslt2L())) ret.add(getRslt2L());
		if(!MCCollectionUtil.contains(ret, getStkChgCndR())) ret.add(getStkChgCndR());
		if(!MCCollectionUtil.contains(ret, getCopyStkChgCndR())) ret.add(getCopyStkChgCndR());
		if(!MCCollectionUtil.contains(ret, getDispStkChgRsltL())) ret.add(getDispStkChgRsltL());
		if(!MCCollectionUtil.contains(ret, getStkChgRsltL())) ret.add(getStkChgRsltL());
		if(!MCCollectionUtil.contains(ret, getStkChgGraphL())) ret.add(getStkChgGraphL());
		if(!MCCollectionUtil.contains(ret, getDlvInstPanelL())) ret.add(getDlvInstPanelL());
		if(!MCCollectionUtil.contains(ret, getIoActL())) ret.add(getIoActL());
		return ret;
	}

	/**
	 * コンテナに対応したブロックのIDを返します。
	 *
	 * 引数のコンテナに対応するブロックがない場合にはnullを返します。<br>
	 * 引数がnullの場合にはnullを返します。<br>
	 *
	 * @return ブロックID
	 */
	public String getBlockId(MCContainer aCnt){
		if(aCnt == null) return null;
		if(aCnt == getCndR()) return "Cnd";
		if(aCnt == getBulkSetR()) return "BulkSet";
		if(aCnt == getRslt1L()) return "Rslt1";
		if(aCnt == getRslt2L()) return "Rslt2";
		if(aCnt == getStkChgCndR()) return "StkChgCnd";
		if(aCnt == getCopyStkChgCndR()) return "CopyStkChgCnd";
		if(aCnt == getDispStkChgRsltL()) return "DispStkChgRslt";
		if(aCnt == getStkChgRsltL()) return "StkChgRslt";
		if(aCnt == getStkChgGraphL()) return "StkChgGraph";
		if(aCnt == getDlvInstPanelL()) return "DlvInstPanel";
		if(aCnt == getIoActL()) return "IoAct";
		return super.getBlockId(aCnt);
	}

	/**
	 * ブロックIDに対応したコンテナを返します。
	 *
	 * 引数のブロックIDに対応するブロックがない場合にはnullを返します。<br>
	 * 引数がnullの場合にはnullを返します。<br>
	 *
	 * @return コンテナ
	 */
	public MCContainer getContainer(String bId){
		if(bId == null) return null;
		if(bId.equals("Cnd")) return getCndR();
		if(bId.equals("BulkSet")) return getBulkSetR();
		if(bId.equals("Rslt1")) return getRslt1L();
		if(bId.equals("Rslt2")) return getRslt2L();
		if(bId.equals("StkChgCnd")) return getStkChgCndR();
		if(bId.equals("CopyStkChgCnd")) return getCopyStkChgCndR();
		if(bId.equals("DispStkChgRslt")) return getDispStkChgRsltL();
		if(bId.equals("StkChgRslt")) return getStkChgRsltL();
		if(bId.equals("StkChgGraph")) return getStkChgGraphL();
		if(bId.equals("DlvInstPanel")) return getDlvInstPanelL();
		if(bId.equals("IoAct")) return getIoActL();
		return super.getContainer(bId);
	}

